        for c in range(w):
            color = src[r][c]
            if color in (0, 1):
                continue

            # Find the 1-region containing the marker, treating the marker as 1.
            # Restrict to its compact bounding box when the region is large.
            seen = {(r, c)}
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if (0 <= yy < h and 0 <= xx < w and
                        src[yy][xx] == 1 and (yy,xx) not in seen):
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            r0, r1 = min(y for y,x in seen), max(y for y,x in seen)
            c0, c1 = min(x for y,x in seen), max(x for y,x in seen)
            # Large connected regions are composites; use a 3x3 local tile.
            if (r1-r0+1)*(c1-c0+1) > 30:
                r0, r1 = max(0,r-1), min(h-1,r+1)
                c0, c1 = max(0,c-1), min(w-1,c+1)
            mask = {(y-r, x-c) for y,x in seen
                    if r0 <= y <= r1 and c0 <= x <= c1}
            if not mask:
                continue
            mh = max(dy for dy,dx in mask)-min(dy for dy,dx in mask)+1
            mw = max(dx for dy,dx in mask)-min(dx for dy,dx in mask)+1
            # Prefer compact local rectangular motifs around the seed.
            mh, mw = min(mh, 3), min(mw, 3)
            for y in range(h-mh+1):
